using System;
using Customization;

public class UomDiagnostic : CustomizationPlugin
{
    public override void UpdateDatabase()
    {
        WriteLog("=== Phase A v5: Single-item UOM change test (item 00004) ===");

        var cs = System.Configuration.ConfigurationManager.ConnectionStrings["ProjectX"];
        if (cs == null) { WriteLog("ERROR: No connection string."); return; }

        string connStr = cs.ConnectionString + ";TrustServerCertificate=True";
        try
        {
            using (var conn = new Microsoft.Data.SqlClient.SqlConnection(connStr))
            {
                conn.Open();

                // Step 0: Find internal InventoryID for item 00004
                int invID = 0;
                using (var cmd = conn.CreateCommand())
                {
                    cmd.CommandText = "SELECT TOP 1 InventoryID FROM InventoryItem WHERE InventoryCD LIKE '00004%' AND StkItem = 1";
                    cmd.CommandTimeout = 10;
                    var result = cmd.ExecuteScalar();
                    if (result != null) invID = (int)result;
                }
                WriteLog($"Item 00004 InventoryID = {invID}");
                if (invID == 0) { WriteLog("ERROR: Item 00004 not found"); return; }

                // Step 1: Check current state
                string currentBase = "";
                using (var cmd = conn.CreateCommand())
                {
                    cmd.CommandText = "SELECT BaseUnit FROM InventoryItem WHERE InventoryID = @id";
                    cmd.Parameters.AddWithValue("@id", invID);
                    cmd.CommandTimeout = 10;
                    currentBase = ((string)cmd.ExecuteScalar() ?? "").Trim();
                }
                WriteLog($"Current BaseUnit = '{currentBase}'");

                if (currentBase == "YDS")
                {
                    WriteLog("Item already has BaseUnit=YDS. Phase A already ran. Skipping.");
                    return;
                }

                // Step 2: Check if YDS→YDS self-conversion exists for this item
                int ydsCount = 0;
                using (var cmd = conn.CreateCommand())
                {
                    cmd.CommandText = @"SELECT COUNT(*) FROM INUnit
                        WHERE UnitType = 1 AND InventoryID = @id
                        AND FromUnit = 'YDS' AND ToUnit = 'YDS'";
                    cmd.Parameters.AddWithValue("@id", invID);
                    cmd.CommandTimeout = 10;
                    ydsCount = (int)cmd.ExecuteScalar();
                }
                WriteLog($"Existing YDS→YDS Type=1 records for this item: {ydsCount}");

                // Step 3: If no YDS→YDS exists, INSERT one by copying from PIECE→PIECE
                if (ydsCount == 0)
                {
                    using (var cmd = conn.CreateCommand())
                    {
                        cmd.CommandText = @"
                            INSERT INTO INUnit (CompanyID, UnitType, ItemClassID, InventoryID,
                                                FromUnit, ToUnit, UnitRate, UnitMultDiv,
                                                PriceAdjustmentMultiplier, CompanyMask,
                                                CreatedByID, CreatedByScreenID, CreatedDateTime,
                                                LastModifiedByID, LastModifiedByScreenID, LastModifiedDateTime)
                            SELECT CompanyID, UnitType, ItemClassID, InventoryID,
                                   'YDS', 'YDS', UnitRate, UnitMultDiv,
                                   PriceAdjustmentMultiplier, CompanyMask,
                                   CreatedByID, CreatedByScreenID, GETUTCDATE(),
                                   LastModifiedByID, LastModifiedByScreenID, GETUTCDATE()
                            FROM INUnit
                            WHERE UnitType = 1 AND InventoryID = @id
                            AND FromUnit = 'PIECE' AND ToUnit = 'PIECE'";
                        cmd.Parameters.AddWithValue("@id", invID);
                        cmd.CommandTimeout = 30;
                        int rows = cmd.ExecuteNonQuery();
                        WriteLog($"Inserted {rows} YDS→YDS self-conversion record(s)");
                    }
                }
                else
                {
                    WriteLog("YDS→YDS already exists, skipping INSERT");
                }

                // Step 4: Change BaseUnit and SalesUnit to YDS
                using (var cmd = conn.CreateCommand())
                {
                    cmd.CommandText = @"UPDATE InventoryItem SET BaseUnit = 'YDS', SalesUnit = 'YDS' WHERE InventoryID = @id";
                    cmd.Parameters.AddWithValue("@id", invID);
                    cmd.CommandTimeout = 10;
                    int rows = cmd.ExecuteNonQuery();
                    WriteLog($"Updated BaseUnit/SalesUnit to YDS ({rows} row)");
                }

                // Step 5: Verify
                using (var cmd = conn.CreateCommand())
                {
                    cmd.CommandText = "SELECT BaseUnit, SalesUnit, PurchaseUnit FROM InventoryItem WHERE InventoryID = @id";
                    cmd.Parameters.AddWithValue("@id", invID);
                    cmd.CommandTimeout = 10;
                    using (var rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            WriteLog($"Post-change: BaseUnit={rdr.GetString(0).Trim()} SalesUnit={rdr.GetString(1).Trim()} PurchaseUnit={rdr.GetString(2).Trim()}");
                        }
                    }
                }

                WriteLog("=== Phase A COMPLETE — verify item 00004 works in Acumatica UI ===");
            }
        }
        catch (Exception ex)
        {
            WriteLog($"ERROR: {ex.Message}");
            WriteLog($"Stack: {ex.StackTrace}");
        }
    }
}
